#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Create a stringstream to hold the markdown string
    std::stringstream ss(markdown);

    // Convert the stringstream to a string
    std::string html;
    ss >> html;

    return html;
}

